// store an attachment, deduplicating by content
function putAttachment(bytes) {
  const hash = sha1(bytes);                 // content address
  if (!blobs.has(hash)) {
    blobs.set(hash, bytes);
    refcount.set(hash, 0);
  }
  refcount.set(hash, refcount.get(hash) + 1);
  return hash;
}

// a message referencing this attachment was deleted
function releaseAttachment(hash) {
  const n = refcount.get(hash) - 1;
  refcount.set(hash, n);
  if (n <= 0) {
    blobs.delete(hash);                     // free the bytes
    refcount.delete(hash);
  }
}
